    previewPresets: [{"labelAr":"نسبة من 0 لـ 100","labelEn":"0 to 100","values":{}},{"labelAr":"مقياس من 0 لـ 10","labelEn":"0 to 10 scale","values":{"MAX_VALUE":10,"STEP_SIZE":1,"START_VALUE":5,"POINTER_SHAPE":"knob"}},{"labelAr":"نسبة بخطوة 5 (سهم)","labelEn":"Steps of 5 (arrow)","values":{"MAX_VALUE":100,"STEP_SIZE":5,"START_VALUE":50,"POINTER_SHAPE":"arrow","POINTER_SIZE":34,"LABEL_POSITION":"below"}},{"labelAr":"مؤشر بشكل SVG خاص","labelEn":"Custom SVG pointer","values":{"POINTER_SHAPE":"custom","POINTER_SVG":"<svg viewBox=\"0 0 40 40\"><path d=\"M20 3 C27 12 32 17 32 24 A12 12 0 0 1 8 24 C8 17 13 12 20 3 Z\" fill=\"currentColor\" stroke=\"#fff\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"24\" r=\"4.5\" fill=\"#fff\"/></svg>","POINTER_SIZE":36,"POINTER_COLOR":"#C35A37","POINTER_HOVER_COLOR":"#8E3D22"}},{"labelAr":"سؤال بإجابة صحيحة (7 أو 8 من 10)","labelEn":"Question with a correct range","values":{"MAX_VALUE":10,"STEP_SIZE":1,"START_VALUE":0,"HAS_TARGET":true,"TARGET_MIN":7,"TARGET_MAX":8,"POINTER_SHAPE":"arrow","POINTER_SIZE":34}}],
    previewHintAr: 'اسحب المؤشر أو اضغط في أي مكان على المسار (ماوس أو تاتش أو قلم) - وأسهم الكيبورد بتحركه خطوة خطوة. "تأكيد الإجابة" بيشتغل لما تفعّل "فيه إجابة صحيحة" أو تختار مثال السؤال.',
    previewHintEn: 'Drag the pointer or tap anywhere on the track (mouse, touch or pen) - arrow keys move it one step. "Check answers" works once a correct range is enabled (or pick the question example).',
